// Batch subarguments are validated against their command's own schema below the envelope layer.
definitions.at(-1)[2].properties.commands.items.properties.arguments = { type: 'object' };
const commandSchemas = new Map(definitions.map(([command, description, schema]) => [command, { command, description, schema }]));

export const envelopeSchema = object({
  command: { type: 'string', minLength: 1 }, arguments: { type: 'object' },
  expectedRevision: integer(), requestId: { type: 'string', minLength: 1, maxLength: 256 }, dryRun: boolean,
}, ['command', 'arguments']);

export const createOptionsSchema = object({ name: text, sampleRate: integer(1),fixedTempo:boolean });

/** Runtime JSON-schema subset. No coercion, silent defaults, unknown keys, NaN or Infinity. */
export function validateSchema(value, schema, path = '$') {
  const bad = (message) => fail('VALIDATION_ERROR', message, { path });
  if (schema.oneOf) {
    const errors = [];
    let matches = 0;
    for (const variant of schema.oneOf) {
      try { validateSchema(value, variant, path); matches++; } catch (error) {
        if (!(error instanceof EngineError)) throw error;
        errors.push({ message: error.message, ...error.details });
      }
    }
    if (matches !== 1) fail('VALIDATION_ERROR', 'Value must match exactly one supported shape.', { path, alternatives: errors });
    return;
  }
  if (Object.hasOwn(schema, 'const') && value !== schema.const) bad(`Expected ${JSON.stringify(schema.const)}.`);
  if (schema.enum && !schema.enum.includes(value)) bad(`Expected one of: ${schema.enum.join(', ')}.`);
  if (schema.type === 'object') {
    if (value === null || typeof value !== 'object' || Array.isArray(value) || ![Object.prototype, null].includes(Object.getPrototypeOf(value))) bad('Expected a plain object.');
    for (const key of schema.required ?? []) if (!Object.hasOwn(value, key)) fail('VALIDATION_ERROR', `Missing required field: ${key}.`, { path: `${path}.${key}` });
    for (const key of Object.keys(value)) {
      const property = schema.properties && Object.hasOwn(schema.properties, key) ? schema.properties[key] : undefined;
      if (!property && schema.additionalProperties === false) fail('VALIDATION_ERROR', `Unknown field: ${key}.`, { path: `${path}.${key}` });
      if (property) validateSchema(value[key], property, `${path}.${key}`);
    }
  } else if (schema.type === 'array') {
    if (!Array.isArray(value)) bad('Expected an array.');
    if (value.length < (schema.minItems ?? 0)) bad(`Expected at least ${schema.minItems} item(s).`);
    if (schema.maxItems !== undefined && value.length > schema.maxItems) bad(`Expected at most ${schema.maxItems} item(s).`);
    if (schema.uniqueItems && new Set(value).size !== value.length) bad('Array items must be unique.');
    for (let index = 0; index < value.length; index++) validateSchema(value[index], schema.items, `${path}[${index}]`);
  } else if (schema.type === 'string') {
    if (typeof value !== 'string') bad('Expected a string.');
    if (schema.minLength !== undefined && value.length < schema.minLength) bad(`String is shorter than ${schema.minLength}.`);
    if (schema.maxLength !== undefined && value.length > schema.maxLength) bad(`String is longer than ${schema.maxLength}.`);
    if (schema.pattern && !new RegExp(schema.pattern).test(value)) bad('String does not match the required format.');
  } else if (schema.type === 'number' || schema.type === 'integer') {
    if (typeof value !== 'number' || !Number.isFinite(value) || (schema.type === 'integer' && !Number.isSafeInteger(value))) bad(`Expected a finite ${schema.type === 'integer' ? 'safe integer' : 'number'}.`);
    if (schema.minimum !== undefined && value < schema.minimum) bad(`Value must be at least ${schema.minimum}.`);
    if (schema.maximum !== undefined && value > schema.maximum) bad(`Value must be at most ${schema.maximum}.`);
  } else if (schema.type === 'boolean' && typeof value !== 'boolean') bad('Expected a boolean.');
}

export function validateCommand(command, args) {
  const definition = commandSchemas.get(command);
  if (!definition) fail('UNKNOWN_COMMAND', `Unknown command: ${command}.`, { command });
  validateSchema(args, definition.schema, '$.arguments');
}

export function getCommandCatalog() {
  return structuredClone([...commandSchemas.values()]);
}
